def classify(record, stage):
    zones = {
        "raw": "unaltered copy exactly as received",
        "bronze": "structured but unprocessed",
        "silver": "cleaned and enriched",
        "gold": "aggregated, ready for reporting",
    }
    return {"stage": stage, "description": zones[stage], "record": record}

events = [{"id": 1, "amount": "19.99", "currency": "usd"}]

pipeline = []
pipeline.append(classify(events[0], "raw"))
cleaned = {"id": 1, "amount": 19.99, "currency": "USD"}
pipeline.append(classify(cleaned, "silver"))
report = {"total_orders": 1, "total_amount": 19.99}
pipeline.append(classify(report, "gold"))

for step in pipeline:
    print(f"{step['stage']}: {step['description']} -> {step['record']}")

